import click


class MyCommand(click.Command):
    pass


def test_explicit_cls_kept_when_group_has_context_settings():
    @click.group(context_settings={"help_option_names": ["-h", "--help"]})
    def cli():
        pass

    @cli.command(cls=MyCommand)
    def sub():
        pass

    assert isinstance(cli.commands["sub"], MyCommand)
    assert type(cli.commands["sub"]) is MyCommand
